"""In-memory ticket rail. Completing a ticket should take it off the active rail."""

from __future__ import annotations

from dataclasses import asdict, dataclass
from typing import Iterable


@dataclass
class Ticket:
    id: int
    title: str
    done: bool = False

    def to_dict(self) -> dict[str, object]:
        return asdict(self)


class TicketStore:
    def __init__(self, items: Iterable[Ticket] | None = None) -> None:
        self._items = list(items or [])
        self._next_id = max((item.id for item in self._items), default=0) + 1

    def all(self) -> list[Ticket]:
        return list(self._items)

    def active(self) -> list[Ticket]:
        return [item for item in self._items if not item.done]

    def add(self, title: str) -> Ticket:
        cleaned = title.strip()
        if not cleaned:
            raise ValueError("ticket title must not be empty")
        ticket = Ticket(id=self._next_id, title=cleaned, done=False)
        self._next_id += 1
        self._items.append(ticket)
        return ticket

    def complete(self, ticket_id: int) -> Ticket:
        ticket = self._require(ticket_id)
        ticket.done = True
        return ticket

    def delete(self, ticket_id: int) -> None:
        self._items = [item for item in self._items if item.id != ticket_id]

    def _require(self, ticket_id: int) -> Ticket:
        for item in self._items:
            if item.id == ticket_id:
                return item
        raise KeyError(f"ticket not found: {ticket_id}")
